def transform(g):
    H,W=len(g),len(g[0])
    bg=9
    pts=[(r,c) for r in range(H) for c in range(W) if g[r][c] not in (bg,1)]
    out=[row[:] for row in g]
    for r,c in pts: out[r][c]=4
    for r,c in pts:
        for rr in range(r+1, H-1):
            if out[rr][c]==bg: out[rr][c]=3
        mc=17+c
        if mc < W:
            for rr in range(1,H):
                if out[rr][mc]==bg: out[rr][mc]=3
    return out

